(66918, 'itIT', '<Il tuo cucciolo ti sorride.>', '', 0),
(66919, 'itIT', '<Il tuo cucciolo cinguetta vedendoti.>', '', 0),
(66920, 'itIT', '<Il tuo cucciolo ti osserva.>', '', 0),
